from alembic import command
from alembic.config import Config


# Sync on purpose: migrations/env.py calls asyncio.run, which cannot nest in a running loop.
def test_migrations_match_models_and_round_trip(alembic_config: Config) -> None:
    command.upgrade(alembic_config, "head")
    # Raises AutogenerateDiffsDetected if the models drifted from the migrations.
    command.check(alembic_config)
    command.downgrade(alembic_config, "base")
    command.upgrade(alembic_config, "head")
